TOP_LEVELS = ("down", "d5", "d4")
TOP_WORDS = ("双头", "衰竭", "顶", "C杀", "失败5", "B反末")


def main():
    import wave_agent as wa
    by = {}
    for d in sorted({p[0] for p in POINTS}):
        cp = os.path.join(DATA, "wave_state_%s.json" % d)
        rec = None
        if os.path.exists(cp):
            try:
                j = json.load(open(cp, encoding="utf-8"))
                if j.get("level"):
                    rec = {k: j.get(k) for k in ("level", "sub_level", "operation")}; rec["src"] = "cache"
            except Exception:
                pass
        if rec is None:
            try:
                f = wa.index_features(d)
                if f is None:
                    rec = {"src": "no_data"}
                else:
                    r = wa.parse(wa.call_agent(wa.build_prompt(f), session="tp_"))
                    rec = {k: r.get(k) for k in ("level", "sub_level", "operation")}; rec["src"] = "llm"
                    json.dump({**rec, "date": d, "reasons": r.get("reasons")}, open(cp, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
            except Exception as e:
                rec = {"src": "err", "err": "%s: %s" % (type(e).__name__, str(e)[:70])}
        by[d] = rec
        print("RUN", d, json.dumps(rec, ensure_ascii=False), flush=True)
    hit = tot = 0
    print("\n%-10s %-30s %-7s %s" % ("date", "level/sub_level/op", "顶态?", "他原话"))
    for d, q in POINTS:
        r = by.get(d) or {}
        lv, sub = str(r.get("level") or "-"), str(r.get("sub_level") or "-")
        ok = (lv in TOP_LEVELS) or any(w in sub for w in TOP_WORDS)
        if r.get("src") in ("err", "no_data"):
            mark = "err"
        else:
            tot += 1; hit += ok; mark = "TOP" if ok else "-"
        print("%-10s %-30s %-7s %s" % (d, "%s/%s/%s" % (lv, sub, r.get("operation") or "-"), mark, q[:40]))
    print("\n关键点顶态命中 %d/%d = %.0f%%" % (hit, tot, 100.0 * hit / tot if tot else 0))


main()
